Explore the top 1000 greatest albums across music history in an interactive visual vinyl archive.

albums = FileAttachment("top_1000_albums.csv").csv({ typed: true })

// Helper to pull the primary genre for grouping and coloring
cleanData = albums.map(d =&gt; ({
  ...d,
  primary_genre: d.genres ? d.genres.split(",")[0].trim() : "other"
}))

// State for currently playing album on the turntable
mutable nowPlaying = cleanData[0]























// Turntable Deck component with integrated tab navigation
html`
&lt;div class="turntable-deck" id="turntable"&gt;
  &lt;div class="platter-area"&gt;
    &lt;div class="vinyl-record"&gt;
      &lt;div class="vinyl-label"&gt;
        &lt;img src="${nowPlaying.image_url}" alt="${nowPlaying.album}" /&gt;
      &lt;/div&gt;
    &lt;/div&gt;
  &lt;/div&gt;
  &lt;div class="deck-info"&gt;
    &lt;div class="deck-nav-bar"&gt;
      &lt;span style="font-size: 0.75rem; font-weight: 700; color: #ffd166; text-transform: uppercase;"&gt;VAULT TABS:&lt;/span&gt;
      &lt;a href="index.qmd" class="deck-nav-pill active"&gt;🎵 Turntable&lt;/a&gt;
      &lt;a href="decades.qmd" class="deck-nav-pill"&gt;📅 Decades Reel ↗&lt;/a&gt;
      &lt;a href="genres.qmd" class="deck-nav-pill"&gt;🎸 Genre Matrix ↗&lt;/a&gt;
      &lt;a href="about.qmd" class="deck-nav-pill"&gt;ℹ️ About ↗&lt;/a&gt;
    &lt;/div&gt;

    &lt;div style="font-size: 0.72rem; letter-spacing: 2px; color: #00f2fe; text-transform: uppercase; font-weight: 700;"&gt;
      ⚡ Active Turntable Platter
    &lt;/div&gt;
    &lt;h2 style="margin: 0.2rem 0 0.1rem 0; font-size: 1.75rem; font-weight: 800; color: #fff; line-height: 1.2;"&gt;
      ${nowPlaying.album}
    &lt;/h2&gt;
    &lt;div style="font-size: 1.05rem; color: #cbd5e1;"&gt;
      ${nowPlaying.artist} &lt;span style="color: #ffd166;"&gt;(${nowPlaying.year})&lt;/span&gt;
    &lt;/div&gt;
    &lt;div style="margin-top: 0.4rem; font-size: 0.85rem; color: #94a3b8;"&gt;
      Rank: &lt;strong style="color: #00f2fe;"&gt;#${nowPlaying.rank}&lt;/strong&gt; of 1000 &nbsp;|&nbsp;
      Rating: &lt;strong style="color: #ffd166;"&gt;⭐ ${nowPlaying.rating.toFixed(2)}&lt;/strong&gt; &nbsp;|&nbsp;
      Genre: &lt;strong style="color: #e2e8f0; text-transform: capitalize;"&gt;${nowPlaying.primary_genre}&lt;/strong&gt;
    &lt;/div&gt;

    &lt;div class="equalizer-wrap"&gt;
      &lt;div class="eq-bar"&gt;&lt;/div&gt;
      &lt;div class="eq-bar"&gt;&lt;/div&gt;
      &lt;div class="eq-bar"&gt;&lt;/div&gt;
      &lt;div class="eq-bar"&gt;&lt;/div&gt;
      &lt;div class="eq-bar"&gt;&lt;/div&gt;
      &lt;div class="eq-bar"&gt;&lt;/div&gt;
      &lt;div class="eq-bar"&gt;&lt;/div&gt;
      &lt;div class="eq-bar"&gt;&lt;/div&gt;
    &lt;/div&gt;

    &lt;div class="deck-controls"&gt;
      &lt;button class="btn-neon" onclick=${() =&gt; {
        const randIndex = Math.floor(Math.random() * cleanData.length);
        mutable nowPlaying = cleanData[randIndex];
      }}&gt;
        🎲 Drop Needle (Random Album)
      &lt;/button&gt;

      &lt;a class="btn btn-outline-light btn-sm" style="display: inline-flex; align-items: center; border-radius: 8px;" target="_blank" href="https://open.spotify.com/search/${encodeURIComponent(nowPlaying.artist + " " + nowPlaying.album)}"&gt;
        🎧 Listen on Spotify ↗
      &lt;/a&gt;
    &lt;/div&gt;
  &lt;/div&gt;
&lt;/div&gt;
`







Top 20 All-Time Legends (Click to Spin)

// Visual ribbon reel of the top 20 critically acclaimed album covers
html`&lt;div class="cover-ribbon"&gt;
  ${cleanData.slice(0, 20).map(d =&gt; html`
    &lt;div class="cover-ribbon-item" title="Click to spin #${d.rank}: ${d.album}" onclick=${() =&gt; {
      mutable nowPlaying = d;
      document.getElementById('turntable').scrollIntoView({ behavior: 'smooth' });
    }}&gt;
      &lt;img class="cover-ribbon-img" src="${d.image_url}" alt="${d.album}" loading="lazy" /&gt;
      &lt;span class="album-badge" style="top: 4px; left: 4px; font-size: 0.68rem; padding: 1px 5px;"&gt;#${d.rank}&lt;/span&gt;
      &lt;div class="cover-ribbon-meta"&gt;
        &lt;div style="font-weight: bold; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: #fff;"&gt;${d.album}&lt;/div&gt;
        &lt;div style="color: #94a3b8; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;"&gt;${d.artist}&lt;/div&gt;
      &lt;/div&gt;
    &lt;/div&gt;
  `)}
&lt;/div&gt;`









viewof search = Inputs.search(cleanData, {
  placeholder: "Search artist, album, genre, or release year..."
})









genresList = ["All", "rock", "pop", "folk", "electronica", "punk", "hip-hop", "soul", "jazz", "country", "metal"]
viewof genreFilter = Inputs.select(genresList, {
  label: "Genre",
  value: "All"
})


















viewof limit = Inputs.select([48, 96, 240, 1000], {
  label: "Display",
  value: 48
})









// Filter data by active search & genre
filtered = search.filter(d =&gt; genreFilter === "All" || d.primary_genre === genreFilter)







md`*Showing ${Math.min(limit, filtered.length)} of ${filtered.length} albums. **Click any album cover below to drop it onto the turntable!***`







// Interactive grid where clicking an album loads it to the turntable
html`&lt;div class="album-grid"&gt;
  ${filtered.slice(0, limit).map(d =&gt; html`
    &lt;div class="album-card" style="cursor: pointer;" onclick=${() =&gt; {
      mutable nowPlaying = d;
      document.getElementById('turntable').scrollIntoView({ behavior: 'smooth' });
    }}&gt;
      &lt;div class="album-cover-wrap"&gt;
        &lt;img class="album-cover-img" src="${d.image_url}" alt="${d.album}" loading="lazy" /&gt;
        &lt;span class="album-badge"&gt;#${d.rank}&lt;/span&gt;
      &lt;/div&gt;
      &lt;div class="album-info"&gt;
        &lt;div class="album-title" title="${d.album}"&gt;${d.album}&lt;/div&gt;
        &lt;div class="album-artist" title="${d.artist}"&gt;
          ${d.artist} &lt;a href="decades.qmd" style="color: #9ba1b0; text-decoration: none;" onclick=${e =&gt; e.stopPropagation()} title="Explore ${d.year} in Decades"&gt;(${d.year} ↗)&lt;/a&gt;
        &lt;/div&gt;
        &lt;div class="album-meta"&gt;
          &lt;span&gt;⭐ ${d.rating.toFixed(2)}&lt;/span&gt;
          &lt;a href="genres.qmd" style="color: #00f2fe; text-transform: capitalize; text-decoration: none;" onclick=${e =&gt; e.stopPropagation()} title="Explore ${d.primary_genre} in Genre Matrix"&gt;${d.primary_genre} ↗&lt;/a&gt;
        &lt;/div&gt;
      &lt;/div&gt;
    &lt;/div&gt;
  `)}
&lt;/div&gt;`

